<?php require __DIR__.'/config.php';
if(is_file($authFile)) { header('Location: index.php'); exit; }
$msg=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $u=trim((string)($_POST['username']??'')); $p=$_POST['password']??''; $c=$_POST['confirm']??''; if(!preg_match('/^[A-Za-z0-9_.-]{3,40}$/',$u)) $msg='Username must be 3-40 characters and use letters, numbers, dot, underscore or hyphen.'; elseif(strlen($p)<10 || $p!==$c) $msg='Use a password of at least 10 characters and make both fields match.'; else { write_json($authFile,['username'=>$u,'password_hash'=>password_hash($p,PASSWORD_DEFAULT),'created_at'=>date('c')]); header('Location: index.php'); exit; }}
?><!doctype html><html><head><meta name="robots" content="noindex,nofollow,noarchive"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>YonoLootZone CMS Setup</title><style>body{font-family:system-ui;background:#f8fafc}.box{max-width:430px;margin:10vh auto;background:white;padding:28px;border-radius:18px;box-shadow:0 10px 35px #0001}input,button{width:100%;padding:12px;margin:8px 0}button{background:#e00068;color:#fff;border:0;border-radius:9px;font-weight:800}</style></head><body><div class="box"><h1>CMS Setup</h1><p>Create the private admin password. Use a strong unique password.</p><?php if($msg):?><p style="color:#b91c1c"><?=h($msg)?></p><?php endif;?><form method="post"><input type="text" name="username" placeholder="Username" autocomplete="username" required><input type="password" name="password" placeholder="Admin password" autocomplete="new-password" required><input type="password" name="confirm" placeholder="Confirm password" required><button>Create CMS Login</button></form></div></body></html>
